Contract ProcessSaleService::makeCashPayment(amount:Real): Boolean {

            precondition:
          CurrentSale.oclIsUndefined() = false and CurrentSale.IsComplete = false and CurrentSale.IsReadytoPay = true and amount >= CurrentSale.Amount

            postcondition:
          let cp:CashPayment in cp.oclIsNew() and CurrentSale.AssoicatedPayment = cp and CurrentSale.BelongedStore.Sales->includes(CurrentSale) and CurrentSale.IsComplete = true and CurrentSale.Time = now and cp.Balance = amount - CurrentSale.Amount and ThirdPartyServices.save(cp) and result = true

        }
